  window.TH_T = function (key) {
    var lang = window.TH_LANG || "en";
    var d = LANGS[lang] || LANGS.en;
    return d[key] || LANGS.en[key] || "";
  };
  window.TH_APPLY_LANG = function (lang) {
    if (!LANGS[lang]) lang = "en";
    window.TH_LANG = lang;
    try { localStorage.setItem("th_lang", lang); } catch (e) {}
    document.documentElement.lang = lang;
    document.documentElement.dir = (lang === "ar" || lang === "ur") ? "rtl" : "ltr";
    document.querySelectorAll("[data-i18n]").forEach(function (el) {
      var v = (LANGS[lang] || LANGS.en)[el.getAttribute("data-i18n")] || LANGS.en[el.getAttribute("data-i18n")];
      if (v) el.textContent = v;
    });
    var sel = document.getElementById("langSelect");
    if (sel) sel.value = lang;
  };
  document.addEventListener("DOMContentLoaded", function () {
    var saved = "en";
    try { saved = localStorage.getItem("th_lang") || "en"; } catch (e) {}
    var sel = document.getElementById("langSelect");
    if (sel) sel.addEventListener("change", function () { window.TH_APPLY_LANG(sel.value); });
    window.TH_APPLY_LANG(saved);
  });
